onClick:
{{
  (() => {
    // 1. Controllo: L'utente ha selezionato delle righe nella tabella?
    if (Table2.selectedRows.length === 0) {
        showAlert('Attenzione: Devi selezionare almeno un articolo da copiare!', 'warning');
    } else {
        // 2. Crea la Testata del pacchetto
        create_pack_header.run()
            .then(() => {
                // 3. Se la testata è ok, crea le Righe
                return create_pack_rows.run();
            })
            .then(() => {
                // 4. Se le righe sono ok, aggiorna il contatore
                return update_cpwarn.run();
            })
            .then(() => {
                // 5. Tutto fatto!
                showAlert('Pacchetto creato con successo!', 'success');
                closeModal('Modal1'); 
            })
            .catch((err) => {
                // Gestione Errori
                showAlert('Errore durante la creazione: ' + err.message, 'error');
            });
    }
  })()
}}
